"use client"

import * as React from "react"
import { useFileUpload } from "@/registry/hooks/use-file-upload"
import { FileUploaderDropzone } from "@/registry/ui/file-uploader/dropzone"
import { FileUploaderList } from "@/registry/ui/file-uploader/list"
import { cn } from "@/lib/utils"

export interface FileUploaderProps extends React.HTMLAttributes<HTMLDivElement> {
    maxFiles?: number
    maxSize?: number
    onUpload?: (files: File[]) => void
}

export function FileUploader({
    className,
    maxFiles = 3,
    maxSize = 1024 * 1024 * 4,
    onUpload,
    ...props
}: FileUploaderProps) {
    const {
        files,
        isHovering,
        error,
        handleDragEnter,
        handleDragLeave,
        handleDrop,
        removeFile,
    } = useFileUpload({ maxFiles, maxSize, onUpload })

    return (
        <div className={cn("w-full space-y-4", className)} {...props}>
            <FileUploaderDropzone
                maxFiles={maxFiles}
                maxSize={maxSize}
                isHovering={isHovering}
                onDragEnter={handleDragEnter}
                onDragLeave={handleDragLeave}
                onDrop={handleDrop}
            />

            {error && (
                <div className="text-sm font-medium text-destructive">{error}</div>
            )}

            <FileUploaderList files={files} onRemove={removeFile} />
        </div>
    )
}

"use client"

import * as React from "react"
import { Upload } from "lucide-react"
import { useFileUpload } from "@/registry/hooks/use-file-upload"
import { formatBytes } from "@/registry/lib/format-bytes"
import { cn } from "@/lib/utils"

export interface FileUploaderDropzoneProps extends React.HTMLAttributes<HTMLDivElement> {
    maxSize: number
    maxFiles: number
    isHovering: boolean
    onDragEnter: (e: React.DragEvent) => void
    onDragLeave: (e: React.DragEvent) => void
    onDrop: (e: React.DragEvent) => void
}

export function FileUploaderDropzone({
    className,
    maxSize,
    maxFiles,
    isHovering,
    onDragEnter,
    onDragLeave,
    onDrop,
    ...props
}: FileUploaderDropzoneProps) {
    return (
        <div
            onDragEnter={onDragEnter}
            onDragOver={onDragEnter}
            onDragLeave={onDragLeave}
            onDrop={onDrop}
            className={cn(
                "flex flex-col items-center justify-center w-full h-64 border-2 border-dashed rounded-lg transition-colors bg-muted/20",
                isHovering ? "border-primary bg-primary/5" : "border-muted-foreground/25",
                "hover:bg-primary/5 hover:border-primary/50 cursor-pointer",
                className
            )}
            {...props}
        >
            <div className="flex flex-col items-center justify-center pt-5 pb-6 pointer-events-none">
                <Upload className="w-10 h-10 mb-3 text-muted-foreground" />
                <p className="mb-2 text-sm text-muted-foreground">
                    <span className="font-semibold text-primary">Click to upload</span> or drag and drop
                </p>
                <p className="text-xs text-muted-foreground">
                    Up to {maxFiles} files, MAX. {formatBytes(maxSize)}
                </p>
            </div>
        </div>
    )
}

import * as React from "react"

export interface UseFileUploadProps {
  accept?: Record<string, string[]>
  maxSize?: number // in bytes
  maxFiles?: number
  onUpload?: (files: File[]) => void
}

export function useFileUpload({
  accept,
  maxSize = 1024 * 1024 * 2, // 2MB
  maxFiles = 1,
  onUpload,
}: UseFileUploadProps = {}) {
  const [files, setFiles] = React.useState<File[]>([])
  const [isHovering, setIsHovering] = React.useState(false)
  const [error, setError] = React.useState<string | null>(null)

  const handleDragEnter = (e: React.DragEvent) => {
    e.preventDefault()
    setIsHovering(true)
  }

  const handleDragLeave = (e: React.DragEvent) => {
    e.preventDefault()
    setIsHovering(false)
  }
  
  const handleDrop = React.useCallback(
    (e: React.DragEvent) => {
      e.preventDefault()
      setIsHovering(false)
      setError(null)

      const droppedFiles = Array.from(e.dataTransfer.files)
      
      if (droppedFiles.length + files.length > maxFiles) {
        setError(`You can only upload up to ${maxFiles} files.`)
        return
      }

      const validFiles = droppedFiles.filter((file) => {
        if (file.size > maxSize) {
          setError(`File > ${Math.round(maxSize / 1024 / 1024)}MB.`)
          return false
        }
        return true
      })

      if (validFiles.length) {
        setFiles((prev) => [...prev, ...validFiles])
        onUpload?.(validFiles)
      }
    },
    [files.length, maxFiles, maxSize, onUpload]
  )

  const removeFile = (index: number) => {
    setFiles((prev) => prev.filter((_, i) => i !== index))
  }

  return {
    files,
    isHovering,
    error,
    handleDragEnter,
    handleDragLeave,
    handleDrop,
    removeFile,
  }
}

export function formatBytes(
  bytes: number,
  opts: {
    decimals?: number
    sizeType?: "accurate" | "normal"
  } = {}
) {
  const { decimals = 0, sizeType = "normal" } = opts
  const sizes = ["Bytes", "KB", "MB", "GB", "TB"]
  const accurateSizes = ["Bytes", "KiB", "MiB", "GiB", "TiB"]
  if (bytes === 0) return "0 Byte"
  const i = Math.floor(Math.log(bytes) / Math.log(1024))
  return `${(bytes / Math.pow(1024, i)).toFixed(decimals)} ${
    sizeType === "accurate" ? accurateSizes[i] ?? "Bytest" : sizes[i] ?? "Bytes"
  }`
}
